import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface WeatherData {
  location: string;
  current: {
    temp: number;
    condition: string;
    description: string;
    humidity: number;
    windSpeed: number;
    feelsLike: number;
    uvIndex: number;
  };
  forecast: Array<{
    day: string;
    high: number;
    low: number;
    condition: string;
  }>;
  aiInsights: string;
}

export interface WeatherNews {
  title: string;
  url: string;
  snippet: string;
  source: string;
  date?: string;
}

export interface RadarData {
  intensity: number; // 0-100
  type: 'rain' | 'snow' | 'clear' | 'thunderstorm';
  coverage: number; // percentage
}

import { GoogleGenAI, Type } from "@google/genai";
import { WeatherData, WeatherNews } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function fetchWeatherInsights(location: string): Promise<WeatherData> {
  const prompt = `Provide detailed current weather conditions and a 5-day forecast for ${location}. 
  Include: temperature (Celsius), conditions, humidity, wind speed, UV index, and feels like temperature.
  Also provide a unique AI insight or recommendation based on this specific weather pattern (e.g., "Great day for outdoor running" or "Potential for late afternoon thunderstorms").`;

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          location: { type: Type.STRING },
          current: {
            type: Type.OBJECT,
            properties: {
              temp: { type: Type.NUMBER },
              condition: { type: Type.STRING },
              description: { type: Type.STRING },
              humidity: { type: Type.NUMBER },
              windSpeed: { type: Type.NUMBER },
              feelsLike: { type: Type.NUMBER },
              uvIndex: { type: Type.NUMBER },
            },
            required: ["temp", "condition", "description", "humidity", "windSpeed", "feelsLike", "uvIndex"]
          },
          forecast: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                day: { type: Type.STRING },
                high: { type: Type.NUMBER },
                low: { type: Type.NUMBER },
                condition: { type: Type.STRING },
              },
              required: ["day", "high", "low", "condition"]
            }
          },
          aiInsights: { type: Type.STRING }
        },
        required: ["location", "current", "forecast", "aiInsights"]
      }
    }
  });

  return JSON.parse(response.text);
}

export async function fetchLiveWeatherNews(location: string): Promise<{ news: WeatherNews[], sourceUrls: string[] }> {
  const prompt = `Find the most recent and relevant live weather news, alerts, and environment updates for ${location}. 
  Focus on breaking news, storm alerts, or seasonal warnings from the last 24-48 hours.`;

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: prompt,
    config: {
      tools: [{ googleSearch: {} }]
    }
  });

  // Extract source URLs from grounding metadata
  const sourceUrls = response.candidates?.[0]?.groundingMetadata?.groundingChunks
    ?.map(chunk => chunk.web?.uri)
    .filter((uri): uri is string => !!uri) || [];

  // Parse the response text into a structured news array
  // We'll ask for a specific JSON structure in a follow-up or refine the prompt
  // For simplicity here, we'll refine the logic to parse a text list
  const newsPrompt = `Summarize the following weather news into a JSON array of objects with 'title', 'url', 'snippet', and 'source'. If URLs are missing, use the search grounding info provided.
  News data: ${response.text}`;

  const structuredResponse = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: newsPrompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            url: { type: Type.STRING },
            snippet: { type: Type.STRING },
            source: { type: Type.STRING }
          },
          required: ["title", "url", "snippet", "source"]
        }
      }
    }
  });

  return {
    news: JSON.parse(structuredResponse.text),
    sourceUrls
  };
}

import React, { useState, useEffect, useCallback } from 'react';
import { Search, MapPin, Wind, Droplets, Sun, AlertTriangle, CloudRain, Newspaper, Radio } from 'lucide-react';
import { fetchWeatherInsights, fetchLiveWeatherNews } from './services/gemini';
import { WeatherData, WeatherNews } from './types';
import WeatherCard from './components/WeatherCard';
import WeatherRadar from './components/WeatherRadar';
import NewsPanel from './components/NewsPanel';
import ForecastChart from './components/ForecastChart';

const App: React.FC = () => {
  const [location, setLocation] = useState<string>('London, UK');
  const [searchInput, setSearchInput] = useState<string>('');
  const [weatherData, setWeatherData] = useState<WeatherData | null>(null);
  const [news, setNews] = useState<WeatherNews[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  const loadData = useCallback(async (loc: string) => {
    setLoading(true);
    setError(null);
    try {
      const [weather, newsData] = await Promise.all([
        fetchWeatherInsights(loc),
        fetchLiveWeatherNews(loc)
      ]);
      setWeatherData(weather);
      setNews(newsData.news);
    } catch (err) {
      console.error(err);
      setError('Failed to fetch weather data. Please try another location.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadData(location);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    if (searchInput.trim()) {
      setLocation(searchInput);
      loadData(searchInput);
    }
  };

  const handleGeoLocation = () => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        async (position) => {
          const { latitude, longitude } = position.coords;
          // Reverse geocode or just use coordinates for Gemini
          const geoLoc = `${latitude.toFixed(2)}, ${longitude.toFixed(2)}`;
          setLocation(geoLoc);
          loadData(geoLoc);
        },
        () => setError('Geolocation permission denied.')
      );
    }
  };

  return (
    <div className="min-h-screen pb-12">
      {/* Navbar */}
      <nav className="sticky top-0 z-50 glass px-4 py-3 mb-6 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <div className="bg-blue-600 p-2 rounded-lg">
            <CloudRain className="text-white w-6 h-6" />
          </div>
          <span className="text-xl font-bold tracking-tight hidden sm:block">SkyWatch <span className="text-blue-400">AI</span></span>
        </div>

        <form onSubmit={handleSearch} className="flex-1 max-w-md mx-4 relative">
          <input
            type="text"
            value={searchInput}
            onChange={(e) => setSearchInput(e.target.value)}
            placeholder="Search location..."
            className="w-full bg-slate-800/50 border border-slate-700 rounded-full py-2 pl-10 pr-4 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all text-sm"
          />
          <Search className="absolute left-3 top-2.5 w-4 h-4 text-slate-400" />
        </form>

        <button 
          onClick={handleGeoLocation}
          className="p-2 hover:bg-slate-800 rounded-full transition-colors text-slate-300"
          title="Use my location"
        >
          <MapPin className="w-5 h-5" />
        </button>
      </nav>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        {error && (
          <div className="bg-red-500/10 border border-red-500/50 text-red-500 p-4 rounded-xl mb-6 flex items-center gap-3">
            <AlertTriangle className="w-5 h-5" />
            <p className="text-sm font-medium">{error}</p>
          </div>
        )}

        {loading ? (
          <div className="flex flex-col items-center justify-center py-24 gap-4">
            <div className="w-12 h-12 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
            <p className="text-slate-400 animate-pulse font-medium">Analyzing atmospheric data...</p>
          </div>
        ) : weatherData ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">

            {/* Left Column: Current Weather & Radar */}
            <div className="lg:col-span-8 space-y-6">
              <WeatherCard data={weatherData} />

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <WeatherRadar condition={weatherData.current.condition} />
                <div className="glass rounded-3xl p-6 flex flex-col justify-between">
                   <div>
                    <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
                      <Radio className="w-5 h-5 text-blue-400" />
                      AI Insights
                    </h3>
                    <p className="text-slate-300 leading-relaxed italic">
                      "{weatherData.aiInsights}"
                    </p>
                   </div>
                   <div className="mt-6 pt-6 border-t border-slate-700/50">
                      <div className="flex justify-between items-center text-xs text-slate-500 uppercase tracking-widest">
                        <span>Reliability Score</span>
                        <span>98%</span>
                      </div>
                      <div className="w-full bg-slate-800 h-1.5 rounded-full mt-2">
                        <div className="bg-blue-500 h-full rounded-full w-[98%]"></div>
                      </div>
                   </div>
                </div>
              </div>

              <ForecastChart forecast={weatherData.forecast} />
            </div>

            {/* Right Column: Live News */}
            <div className="lg:col-span-4">
              <NewsPanel news={news} location={weatherData.location} />
            </div>

          </div>
        ) : null}
      </main>
    </div>
  );
};

export default App;

