import React, { useMemo } from 'react';
import { Radio } from 'lucide-react';

interface WeatherRadarProps {
  condition: string;
}

const WeatherRadar: React.FC<WeatherRadarProps> = ({ condition }) => {
  // Generate a random seed for visual distribution
  const dots = useMemo(() => {
    const isPrecip = condition.toLowerCase().includes('rain') || condition.toLowerCase().includes('storm');
    return Array.from({ length: isPrecip ? 40 : 10 }).map((_, i) => ({
      x: Math.random() * 100,
      y: Math.random() * 100,
      size: Math.random() * 15 + 5,
      opacity: Math.random() * 0.6 + 0.2,
      color: isPrecip ? 'bg-blue-500' : 'bg-green-500/30'
    }));
  }, [condition]);

  return (
    <div className="glass rounded-3xl p-6 flex flex-col h-[320px]">
      <div className="flex justify-between items-center mb-4">
        <h3 className="text-lg font-semibold flex items-center gap-2">
          <Radio className="w-5 h-5 text-green-400" />
          AI Radar Scan
        </h3>
        <span className="px-2 py-1 rounded bg-green-500/10 text-green-500 text-[10px] font-bold uppercase tracking-wider animate-pulse">
          Live Analysis
        </span>
      </div>

      <div className="flex-1 relative radar-scan bg-slate-900 rounded-2xl border border-slate-800 overflow-hidden">
        {/* Radar concentric circles */}
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
          <div className="w-1/4 h-1/4 border border-slate-700/50 rounded-full"></div>
          <div className="absolute w-1/2 h-1/2 border border-slate-700/50 rounded-full"></div>
          <div className="absolute w-3/4 h-3/4 border border-slate-700/50 rounded-full"></div>
          {/* Crosshairs */}
          <div className="absolute w-full h-[1px] bg-slate-700/30"></div>
          <div className="absolute h-full w-[1px] bg-slate-700/30"></div>
        </div>

        {/* Radar "clouds" / "echoes" */}
        {dots.map((dot, i) => (
          <div
            key={i}
            className={`absolute rounded-full blur-md ${dot.color}`}
            style={{
              left: `${dot.x}%`,
              top: `${dot.y}%`,
              width: `${dot.size}px`,
              height: `${dot.size}px`,
              opacity: dot.opacity
            }}
          ></div>
        ))}
      </div>

      <div className="mt-4 flex justify-between text-xs text-slate-500">
        <span>Scanned Range: 250km</span>
        <span>Refresh Rate: 2s</span>
      </div>
    </div>
  );
};

export default WeatherRadar;

