import React, { useMemo, useState, useRef, useEffect } from 'react';
import { Radio, Plus, Minus, Maximize2, Clock } from 'lucide-react';

interface WeatherRadarProps {
  condition: string;
}

const WeatherRadar: React.FC<WeatherRadarProps> = ({ condition }) => {
  const [scale, setScale] = useState(1);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const [scanTime, setScanTime] = useState(new Date().toLocaleTimeString());

  const containerRef = useRef<HTMLDivElement>(null);

  // Update scan time every 10 seconds to simulate radar intervals
  useEffect(() => {
    const timer = setInterval(() => {
      setScanTime(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }));
    }, 10000);
    return () => clearInterval(timer);
  }, []);

  // Generate random echoes based on condition
  const dots = useMemo(() => {
    const isPrecip = condition.toLowerCase().includes('rain') || condition.toLowerCase().includes('storm');
    return Array.from({ length: isPrecip ? 60 : 15 }).map((_, i) => ({
      x: Math.random() * 200 - 50, // Wider range for panning
      y: Math.random() * 200 - 50,
      size: Math.random() * 25 + 10,
      opacity: Math.random() * 0.6 + 0.2,
      color: isPrecip ? 'bg-blue-500' : 'bg-green-500/30'
    }));
  }, [condition]);

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsDragging(true);
    setDragStart({ x: e.clientX - position.x, y: e.clientY - position.y });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    setPosition({
      x: e.clientX - dragStart.x,
      y: e.clientY - dragStart.y
    });
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  const handleWheel = (e: React.WheelEvent) => {
    const delta = e.deltaY > 0 ? 0.9 : 1.1;
    setScale(prev => Math.min(Math.max(prev * delta, 0.5), 4));
  };

  const resetView = () => {
    setScale(1);
    setPosition({ x: 0, y: 0 });
  };

  const zoomIn = () => setScale(prev => Math.min(prev + 0.2, 4));
  const zoomOut = () => setScale(prev => Math.max(prev - 0.2, 0.5));

  return (
    <div className="glass rounded-3xl p-6 flex flex-col h-[400px] select-none">
      <div className="flex justify-between items-center mb-4">
        <h3 className="text-lg font-semibold flex items-center gap-2">
          <Radio className="w-5 h-5 text-green-400" />
          Interactive AI Radar
        </h3>
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-1.5 px-2 py-1 rounded bg-slate-800 text-[10px] text-slate-400 border border-slate-700">
            <Clock className="w-3 h-3" />
            <span>Scan: {scanTime}</span>
          </div>
          <span className="px-2 py-1 rounded bg-green-500/10 text-green-500 text-[10px] font-bold uppercase tracking-wider animate-pulse">
            Live
          </span>
        </div>
      </div>

      <div 
        ref={containerRef}
        className={`flex-1 relative bg-slate-900 rounded-2xl border border-slate-800 overflow-hidden cursor-${isDragging ? 'grabbing' : 'grab'}`}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        onWheel={handleWheel}
      >
        {/* Radar Map Content */}
        <div 
          className="absolute inset-0 transition-transform duration-75 ease-out origin-center"
          style={{ 
            transform: `translate(${position.x}px, ${position.y}px) scale(${scale})` 
          }}
        >
          {/* Static Background Grid */}
          <div className="absolute inset-[-100%] grid grid-cols-12 grid-rows-12 pointer-events-none opacity-20">
            {Array.from({ length: 144 }).map((_, i) => (
              <div key={i} className="border-[0.5px] border-slate-700"></div>
            ))}
          </div>

          {/* Radar concentric circles centered in the "world" */}
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 flex items-center justify-center pointer-events-none w-full h-full">
            <div className="w-[10%] h-[10%] border border-slate-700/50 rounded-full"></div>
            <div className="absolute w-[30%] h-[30%] border border-slate-700/50 rounded-full"></div>
            <div className="absolute w-[60%] h-[60%] border border-slate-700/50 rounded-full"></div>
            <div className="absolute w-[90%] h-[90%] border border-slate-700/50 rounded-full"></div>
            <div className="absolute w-[120%] h-[120%] border border-slate-700/50 rounded-full"></div>

            <div className="absolute w-full h-[1px] bg-slate-700/30"></div>
            <div className="absolute h-full w-[1px] bg-slate-700/30"></div>
          </div>

          {/* Radar "clouds" / "echoes" */}
          {dots.map((dot, i) => (
            <div
              key={i}
              className={`absolute rounded-full blur-xl ${dot.color}`}
              style={{
                left: `${dot.x}%`,
                top: `${dot.y}%`,
                width: `${dot.size}px`,
                height: `${dot.size}px`,
                opacity: dot.opacity
              }}
            ></div>
          ))}
        </div>

        {/* Floating Controls */}
        <div className="absolute bottom-4 right-4 flex flex-col gap-2">
          <button 
            onClick={(e) => { e.stopPropagation(); zoomIn(); }}
            className="p-2 bg-slate-800/80 hover:bg-slate-700 border border-slate-600 rounded-lg text-white transition-colors"
          >
            <Plus className="w-4 h-4" />
          </button>
          <button 
            onClick={(e) => { e.stopPropagation(); zoomOut(); }}
            className="p-2 bg-slate-800/80 hover:bg-slate-700 border border-slate-600 rounded-lg text-white transition-colors"
          >
            <Minus className="w-4 h-4" />
          </button>
          <button 
            onClick={(e) => { e.stopPropagation(); resetView(); }}
            className="p-2 bg-slate-800/80 hover:bg-slate-700 border border-slate-600 rounded-lg text-white transition-colors"
          >
            <Maximize2 className="w-4 h-4" />
          </button>
        </div>

        {/* Global Sweep Line (Stays fixed to UI or follows center?)
            Let's keep it fixed to the visual center for a "radar station" feel */}
        <div className="absolute inset-0 pointer-events-none radar-scan opacity-40"></div>
      </div>

      <div className="mt-4 flex justify-between text-[10px] text-slate-500 uppercase tracking-widest font-bold">
        <span>Zoom: {Math.round(scale * 100)}%</span>
        <span>Drag to Pan Map</span>
      </div>
    </div>
  );
};

