import { GoogleGenAI, Type } from "@google/genai";
import { WeatherData, WeatherNews, HistoricalWeatherData, RadarSnapshot } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function fetchWeatherInsights(location: string): Promise<WeatherData> {
  const prompt = `Provide detailed current weather conditions and a 5-day forecast for ${location}. 
  Include: temperature (Celsius), conditions, humidity, wind speed, UV index, and feels like temperature.
  Also provide a unique AI insight or recommendation based on this specific weather pattern (e.g., "Great day for outdoor running" or "Potential for late afternoon thunderstorms").`;

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          location: { type: Type.STRING },
          current: {
            type: Type.OBJECT,
            properties: {
              temp: { type: Type.NUMBER },
              condition: { type: Type.STRING },
              description: { type: Type.STRING },
              humidity: { type: Type.NUMBER },
              windSpeed: { type: Type.NUMBER },
              feelsLike: { type: Type.NUMBER },
              uvIndex: { type: Type.NUMBER },
            },
            required: ["temp", "condition", "description", "humidity", "windSpeed", "feelsLike", "uvIndex"]
          },
          forecast: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                day: { type: Type.STRING },
                high: { type: Type.NUMBER },
                low: { type: Type.NUMBER },
                condition: { type: Type.STRING },
              },
              required: ["day", "high", "low", "condition"]
            }
          },
          aiInsights: { type: Type.STRING }
        },
        required: ["location", "current", "forecast", "aiInsights"]
      }
    }
  });

  return JSON.parse(response.text);
}

export async function fetchLiveWeatherNews(location: string): Promise<{ news: WeatherNews[], sourceUrls: string[] }> {
  const prompt = `Find the most recent and relevant live weather news, alerts, and environment updates for ${location}. 
  Focus on breaking news, storm alerts, or seasonal warnings from the last 24-48 hours.`;

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: prompt,
    config: {
      tools: [{ googleSearch: {} }]
    }
  });

  const sourceUrls = response.candidates?.[0]?.groundingMetadata?.groundingChunks
    ?.map(chunk => chunk.web?.uri)
    .filter((uri): uri is string => !!uri) || [];

  const newsPrompt = `Summarize the following weather news into a JSON array of objects with 'title', 'url', 'snippet', and 'source'. If URLs are missing, use the search grounding info provided.
  News data: ${response.text}`;

  const structuredResponse = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: newsPrompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            url: { type: Type.STRING },
            snippet: { type: Type.STRING },
            source: { type: Type.STRING }
          },
          required: ["title", "url", "snippet", "source"]
        }
      }
    }
  });

  return {
    news: JSON.parse(structuredResponse.text),
    sourceUrls
  };
}

export async function fetchHistoricalWeather(location: string, date: string): Promise<HistoricalWeatherData> {
  const searchPrompt = `What was the weather like in ${location} on ${date}? Find high/low temperatures, precipitation, and general conditions.`;

  const searchResponse = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: searchPrompt,
    config: {
      tools: [{ googleSearch: {} }]
    }
  });

  const sourceUrls = searchResponse.candidates?.[0]?.groundingMetadata?.groundingChunks
    ?.map(chunk => chunk.web?.uri)
    .filter((uri): uri is string => !!uri) || [];

  const extractionPrompt = `Convert the following weather information for ${location} on ${date} into a structured JSON object. 
  Include: highTemp (number), lowTemp (number), avgTemp (number), precipitation (string), conditions (string), summary (string), and sources (array of strings).
  Information to parse: ${searchResponse.text}`;

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: extractionPrompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          date: { type: Type.STRING },
          location: { type: Type.STRING },
          highTemp: { type: Type.NUMBER },
          lowTemp: { type: Type.NUMBER },
          avgTemp: { type: Type.NUMBER },
          precipitation: { type: Type.STRING },
          conditions: { type: Type.STRING },
          summary: { type: Type.STRING },
          sources: { 
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["date", "location", "highTemp", "lowTemp", "avgTemp", "precipitation", "conditions", "summary"]
      }
    }
  });

  const data = JSON.parse(response.text);
  if (!data.sources || data.sources.length === 0) {
    data.sources = sourceUrls.slice(0, 3);
  }
  return data;
}

export async function fetchRadarSnapshot(location: string): Promise<RadarSnapshot> {
  const searchPrompt = `Find actual current radar data, precipitation intensity, and movement for ${location}. 
  Identify specific areas of rain, snow, or storms relative to the city center (e.g., '10 miles north-east', 'scattered showers to the west').`;

  const searchResponse = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: searchPrompt,
    config: {
      tools: [{ googleSearch: {} }]
    }
  });

  const extractionPrompt = `Based on this radar report: "${searchResponse.text}", 
  create a structured JSON object for a radar visualization.
  The 'echoes' should be an array of objects with: 
  - x: horizontal position from center (-100 to 100)
  - y: vertical position from center (-100 to 100)
  - intensity: 0 to 1 (0.2 for light, 0.9 for heavy)
  - type: 'rain', 'snow', 'hail', or 'storm'
  - size: diameter in pixels (10 to 80)
  Include a short text summary.`;

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: extractionPrompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          timestamp: { type: Type.STRING },
          summary: { type: Type.STRING },
          echoes: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                x: { type: Type.NUMBER },
                y: { type: Type.NUMBER },
                intensity: { type: Type.NUMBER },
                type: { type: Type.STRING },
                size: { type: Type.NUMBER }
              },
              required: ["x", "y", "intensity", "type", "size"]
            }
          }
        },
        required: ["timestamp", "summary", "echoes"]
      }
    }
  });

  return JSON.parse(response.text);
}

import React, { useState, useRef, useEffect } from 'react';
import { Radio, Plus, Minus, Maximize2, Clock, Info } from 'lucide-react';
import { RadarSnapshot } from '../types';

interface WeatherRadarProps {
  snapshot: RadarSnapshot | null;
}

const WeatherRadar: React.FC<WeatherRadarProps> = ({ snapshot }) => {
  const [scale, setScale] = useState(1);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  const containerRef = useRef<HTMLDivElement>(null);

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsDragging(true);
    setDragStart({ x: e.clientX - position.x, y: e.clientY - position.y });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    setPosition({
      x: e.clientX - dragStart.x,
      y: e.clientY - dragStart.y
    });
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  const handleWheel = (e: React.WheelEvent) => {
    const delta = e.deltaY > 0 ? 0.9 : 1.1;
    setScale(prev => Math.min(Math.max(prev * delta, 0.5), 4));
  };

  const resetView = () => {
    setScale(1);
    setPosition({ x: 0, y: 0 });
  };

  const zoomIn = () => setScale(prev => Math.min(prev + 0.2, 4));
  const zoomOut = () => setScale(prev => Math.max(prev - 0.2, 0.5));

  const getEchoColor = (type: string, intensity: number) => {
    if (type === 'snow') return 'bg-white';
    if (type === 'hail') return 'bg-cyan-200';
    if (type === 'storm') return 'bg-purple-600';

    // Rain intensity gradient
    if (intensity > 0.8) return 'bg-red-500';
    if (intensity > 0.6) return 'bg-orange-500';
    if (intensity > 0.4) return 'bg-yellow-500';
    if (intensity > 0.2) return 'bg-green-500';
    return 'bg-blue-500';
  };

  return (
    <div className="glass rounded-3xl p-6 flex flex-col h-[400px] select-none">
      <div className="flex justify-between items-center mb-4">
        <h3 className="text-lg font-semibold flex items-center gap-2">
          <Radio className="w-5 h-5 text-green-400" />
          Atmospheric Radar
        </h3>
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-1.5 px-2 py-1 rounded bg-slate-800 text-[10px] text-slate-400 border border-slate-700">
            <Clock className="w-3 h-3" />
            <span>Actual: {snapshot?.timestamp || 'N/A'}</span>
          </div>
          <span className="px-2 py-1 rounded bg-green-500/10 text-green-500 text-[10px] font-bold uppercase tracking-wider">
            Verified
          </span>
        </div>
      </div>

      <div 
        ref={containerRef}
        className={`flex-1 relative bg-slate-900 rounded-2xl border border-slate-800 overflow-hidden cursor-${isDragging ? 'grabbing' : 'grab'}`}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        onWheel={handleWheel}
      >
        <div 
          className="absolute inset-0 transition-transform duration-75 ease-out origin-center"
          style={{ 
            transform: `translate(${position.x}px, ${position.y}px) scale(${scale})` 
          }}
        >
          {/* Background Grid */}
          <div className="absolute inset-[-100%] grid grid-cols-12 grid-rows-12 pointer-events-none opacity-20">
            {Array.from({ length: 144 }).map((_, i) => (
              <div key={i} className="border-[0.5px] border-slate-700"></div>
            ))}
          </div>

          {/* Centered rings */}
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 flex items-center justify-center pointer-events-none w-full h-full">
            {[10, 30, 60, 90, 120].map(size => (
              <div key={size} className="absolute border border-slate-700/50 rounded-full" style={{ width: `${size}%`, height: `${size}%` }}></div>
            ))}
            <div className="absolute w-full h-[1px] bg-slate-700/30"></div>
            <div className="absolute h-full w-[1px] bg-slate-700/30"></div>
          </div>

          {/* Real Radar Echoes */}
          {snapshot?.echoes.map((echo, i) => (
            <div
              key={i}
              className={`absolute rounded-full blur-xl transition-all duration-1000 ${getEchoColor(echo.type, echo.intensity)}`}
              style={{
                left: `${50 + (echo.x / 2)}%`, // Convert -100/100 to 0/100
                top: `${50 + (echo.y / 2)}%`,
                width: `${echo.size}px`,
                height: `${echo.size}px`,
                opacity: 0.3 + (echo.intensity * 0.6)
              }}
            ></div>
          ))}
        </div>

        {/* Floating Controls */}
        <div className="absolute bottom-4 right-4 flex flex-col gap-2">
          <button onClick={zoomIn} className="p-2 bg-slate-800/80 hover:bg-slate-700 border border-slate-600 rounded-lg text-white"><Plus className="w-4 h-4" /></button>
          <button onClick={zoomOut} className="p-2 bg-slate-800/80 hover:bg-slate-700 border border-slate-600 rounded-lg text-white"><Minus className="w-4 h-4" /></button>
          <button onClick={resetView} className="p-2 bg-slate-800/80 hover:bg-slate-700 border border-slate-600 rounded-lg text-white"><Maximize2 className="w-4 h-4" /></button>
        </div>

        <div className="absolute inset-0 pointer-events-none radar-scan opacity-40"></div>
      </div>

      {snapshot?.summary && (
        <div className="mt-3 flex items-start gap-2 p-2 bg-slate-800/30 rounded-lg border border-slate-700/50">
          <Info className="w-4 h-4 text-blue-400 shrink-0 mt-0.5" />
          <p className="text-[10px] text-slate-300 leading-tight">{snapshot.summary}</p>
        </div>
      )}

      <div className="mt-auto flex justify-between text-[10px] text-slate-500 uppercase tracking-widest font-bold">
        <span>Intensity Index: {snapshot?.echoes.length ? 'Active' : 'Clear'}</span>
        <span>AI-Analyzed Imagery</span>
      </div>
    </div>
  );
};

export default WeatherRadar;

import React, { useState, useEffect, useCallback } from 'react';
import { Search, MapPin, AlertTriangle, CloudRain, Radio } from 'lucide-react';
import { fetchWeatherInsights, fetchLiveWeatherNews, fetchRadarSnapshot } from './services/gemini';
import { WeatherData, WeatherNews, RadarSnapshot } from './types';
import WeatherCard from './components/WeatherCard';
import WeatherRadar from './components/WeatherRadar';
import NewsPanel from './components/NewsPanel';
import ForecastChart from './components/ForecastChart';
import HistoricalPanel from './components/HistoricalPanel';

const App: React.FC = () => {
  const [location, setLocation] = useState<string>('London, UK');
  const [searchInput, setSearchInput] = useState<string>('');
  const [weatherData, setWeatherData] = useState<WeatherData | null>(null);
  const [news, setNews] = useState<WeatherNews[]>([]);
  const [radarSnapshot, setRadarSnapshot] = useState<RadarSnapshot | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  const loadData = useCallback(async (loc: string) => {
    setLoading(true);
    setError(null);
    try {
      const [weather, newsData, radar] = await Promise.all([
        fetchWeatherInsights(loc),
        fetchLiveWeatherNews(loc),
        fetchRadarSnapshot(loc)
      ]);
      setWeatherData(weather);
      setNews(newsData.news);
      setRadarSnapshot(radar);
    } catch (err) {
      console.error(err);
      setError('Failed to fetch weather data. Please try another location.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadData(location);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    if (searchInput.trim()) {
      setLocation(searchInput);
      loadData(searchInput);
    }
  };

  const handleGeoLocation = () => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        async (position) => {
          const { latitude, longitude } = position.coords;
          const geoLoc = `${latitude.toFixed(2)}, ${longitude.toFixed(2)}`;
          setLocation(geoLoc);
          loadData(geoLoc);
        },
        () => setError('Geolocation permission denied.')
      );
    }
  };

  return (
    <div className="min-h-screen pb-12">
      {/* Navbar */}
      <nav className="sticky top-0 z-50 glass px-4 py-3 mb-6 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <div className="bg-blue-600 p-2 rounded-lg shadow-lg shadow-blue-500/20">
            <CloudRain className="text-white w-6 h-6" />
          </div>
          <span className="text-xl font-bold tracking-tight hidden sm:block">SkyWatch <span className="text-blue-400">AI</span></span>
        </div>

        <form onSubmit={handleSearch} className="flex-1 max-w-md mx-4 relative">
          <input
            type="text"
            value={searchInput}
            onChange={(e) => setSearchInput(e.target.value)}
            placeholder="Search location..."
            className="w-full bg-slate-800/50 border border-slate-700 rounded-full py-2 pl-10 pr-4 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all text-sm text-white"
          />
          <Search className="absolute left-3 top-2.5 w-4 h-4 text-slate-400" />
        </form>

        <button 
          onClick={handleGeoLocation}
          className="p-2 hover:bg-slate-800 rounded-full transition-colors text-slate-300"
          title="Use my location"
        >
          <MapPin className="w-5 h-5" />
        </button>
      </nav>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        {error && (
          <div className="bg-red-500/10 border border-red-500/50 text-red-500 p-4 rounded-xl mb-6 flex items-center gap-3">
            <AlertTriangle className="w-5 h-5" />
            <p className="text-sm font-medium">{error}</p>
          </div>
        )}

        {loading ? (
          <div className="flex flex-col items-center justify-center py-24 gap-4">
            <div className="w-12 h-12 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
            <p className="text-slate-400 animate-pulse font-medium">Synthesizing radar data...</p>
          </div>
        ) : weatherData ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">

            <div className="lg:col-span-8 space-y-6">
              <WeatherCard data={weatherData} />

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <WeatherRadar snapshot={radarSnapshot} />
                <div className="glass rounded-3xl p-6 flex flex-col justify-between">
                   <div>
                    <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
                      <Radio className="w-5 h-5 text-blue-400" />
                      AI Prediction Engine
                    </h3>
                    <p className="text-slate-300 leading-relaxed italic">
                      "{weatherData.aiInsights}"
                    </p>
                   </div>
                   <div className="mt-6 pt-6 border-t border-slate-700/50">
                      <div className="flex justify-between items-center text-xs text-slate-500 uppercase tracking-widest">
                        <span>Reliability Score</span>
                        <span>98%</span>
                      </div>
                      <div className="w-full bg-slate-800 h-1.5 rounded-full mt-2">
                        <div className="bg-blue-500 h-full rounded-full w-[98%]"></div>
                      </div>
                   </div>
                </div>
              </div>

              <ForecastChart forecast={weatherData.forecast} />
            </div>

            <div className="lg:col-span-4 space-y-6">
              <HistoricalPanel location={weatherData.location} />
              <NewsPanel news={news} location={weatherData.location} />
            </div>

          </div>
        ) : null}
      </main>
    </div>
  );
};

export default App;

