import React from 'react';
import { AreaChart, Area, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid } from 'recharts';
import { Cloud, Sun, CloudRain, CloudLightning } from 'lucide-react';

interface ForecastDay {
  day: string;
  high: number;
  low: number;
  condition: string;
  windSpeedHigh: number;
  windSpeedLow: number;
  windDirection: string;
}

interface ForecastChartProps {
  forecast: ForecastDay[];
}

const ForecastChart: React.FC<ForecastChartProps> = ({ forecast }) => {
  const chartData = forecast.map(f => ({
    name: f.day,
    temp: f.high,
    low: f.low
  }));

  const getWeatherIcon = (condition: string) => {
    const c = condition.toLowerCase();
    if (c.includes('sunny') || c.includes('clear')) return <Sun className="w-5 h-5 text-yellow-400" />;
    if (c.includes('rain')) return <CloudRain className="w-5 h-5 text-blue-400" />;
    if (c.includes('storm') || c.includes('thunder')) return <CloudLightning className="w-5 h-5 text-purple-400" />;
    return <Cloud className="w-5 h-5 text-slate-400" />;
  };

  return (
    <div className="glass rounded-3xl p-6">
      <h3 className="text-lg font-semibold mb-6">5-Day Forecast Trends</h3>

      <div className="h-[240px] w-full">
        <ResponsiveContainer width="100%" height="100%">
          <AreaChart data={chartData}>
            <defs>
              <linearGradient id="colorTemp" x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.3}/>
                <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
              </linearGradient>
            </defs>
            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#334155" />
            <XAxis 
              dataKey="name" 
              axisLine={false} 
              tickLine={false} 
              tick={{fill: '#94a3b8', fontSize: 12}} 
              dy={10}
            />
            <YAxis 
              hide 
              domain={['dataMin - 5', 'dataMax + 5']} 
            />
            <Tooltip 
              contentStyle={{ backgroundColor: '#1e293b', border: '1px solid #334155', borderRadius: '12px' }}
              itemStyle={{ color: '#f8fafc' }}
            />
            <Area 
              type="monotone" 
              dataKey="temp" 
              stroke="#3b82f6" 
              strokeWidth={3}
              fillOpacity={1} 
              fill="url(#colorTemp)" 
              animationDuration={1500}
            />
          </AreaChart>
        </ResponsiveContainer>
      </div>

      <div className="grid grid-cols-5 gap-2 mt-8">
        {forecast.map((f, i) => (
          <div key={i} className="flex flex-col items-center gap-2 p-3 bg-slate-800/40 rounded-2xl border border-slate-700/50">
            <span className="text-xs font-bold text-slate-400 uppercase tracking-tighter">{f.day}</span>
            {getWeatherIcon(f.condition)}
            <div className="flex flex-col items-center mt-1">
              <span className="text-lg font-bold text-white">{f.high}°</span>
              <span className="text-[10px] text-slate-500">{f.low}°</span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

