          },
          forecast: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                day: { type: Type.STRING },
                high: { type: Type.NUMBER },
                low: { type: Type.NUMBER },
                condition: { type: Type.STRING },
                windSpeedHigh: { type: Type.NUMBER },
                windSpeedLow: { type: Type.NUMBER },
                windDirection: { type: Type.STRING },
