                  className={`absolute top-1 bottom-1 w-[calc(50%-4px)] bg-blue-600 rounded-lg shadow-lg shadow-blue-500/20 transition-all duration-300 ease-out ${isMetric ? 'left-1' : 'left-[calc(50%+1px)]'}`}
